 "content": "def transform(grid):
    out = [row[:] for row in grid]
    # A straight colored ray is the palette sample. Recolor the connected
    # shape made from the ray's color, leaving other shapes unchanged.
    h, w = len(grid), len(grid[0])
    bg = max(set(v for row in grid for v in row), key=lambda x: sum(row.count(x) for row in grid))
    # Find long straight runs of a non-background color (the ray).
    runs=[]
    for r in range(h):
        c=0
        while c<w:
            if grid[r][c]==bg: c+=1; continue
            col=grid[r][c]; e=c+1
            while e<w and grid[r][e]==col: e+=1
            if e-c>=5: runs.append((col,e-c));
            c=e
    for c in range(w):
        r=0
        while r<h:
            if grid[r][c]==bg: r+=1; continue
            col=grid[r][c]; e=r+1
            while e<h and grid[e][c]==col: e+=1
            if e-r>=5: runs.append((col,e-r))
            r=e
    if not runs: return out
    ray_color=max(runs,key=lambda x:x[1])[0]
    # Recolor only bounded, compact components of the ray color, not the ray.
    seen=set()
    for r in range(h):
        for c in range(w):
            if grid[r][c]!=ray_color or (r,c) in seen: continue
            comp=[]; stack=[(r,c)]; seen.add((r,c))
            while stack:
                y,x=stack.pop(); comp.append((y,x))
                for p in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    yy,xx=p
                    if 0<=yy<h and 0<=xx<w and grid[yy][xx]==ray_color and p not in seen:
                        seen.add(p); stack.append(p)
            if len(comp)>1 and len(comp)<10:
                for y,x in comp: out[y][x]=bg
    return out
