    """Recolor the small object aligned with the long guide stroke."""
    out=[row[:] for row in grid]
    h=len(grid); w=min(map(len,grid))
    bg=max(set(v for row in grid for v in row),key=lambda x:sum(row.count(x) for row in grid))
    # Find longest non-background horizontal/vertical run as the guide color.
    runs=[]
    for r in range(h):
        for c in range(w):
            v=grid[r][c]
            if v==bg: continue
            if c==0 or grid[r][c-1]!=v:
                e=c
                while e<w and grid[r][e]==v: e+=1
                if e-c>=5: runs.append((e-c,v,(r,(c+e-1)/2),'h'))
    for c in range(w):
        for r in range(h):
            v=grid[r][c]
            if v==bg: continue
            if r==0 or grid[r-1][c]!=v:
                e=r
                while e<h and grid[e][c]==v: e+=1
                if e-r>=5: runs.append((e-r,v,((r+e-1)/2,c),'v'))
    if not runs: return out
    _,color,center,orient=max(runs,key=lambda x:x[0])
    # Collect compact components, excluding the guide color itself.
    comps=[]
    for col in set(v for row in grid for v in row if v not in (bg,color)):
        unseen={(r,c) for r in range(h) for c in range(w) if grid[r][c]==col}
        while unseen:
            s=unseen.pop(); comp={s}; stack=[s]
            while stack:
                r,c=stack.pop()
                for dr in (-1,0,1):
                    for dc in (-1,0,1):
                        p=(r+dr,c+dc)
                        if p in unseen: unseen.remove(p); comp.add(p); stack.append(p)
            if 2<=len(comp)<=12:
