 "content": "def transform(grid):
    out=[row[:] for row in grid]
    # The long 2 guide marks the small isolated zero pair aligned below it.
    # Recolor that compact two-cell vertical component to the guide color.
    h=len(grid); w=min(len(r) for r in grid)
    unseen={(r,c) for r in range(h) for c in range(w) if grid[r][c]==0}
    while unseen:
        s=unseen.pop(); comp={s}; stack=[s]
        while stack:
            r,c=stack.pop()
            for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                p=(r+dr,c+dc)
                if p in unseen:
                    unseen.remove(p); comp.add(p); stack.append(p)
        if len(comp)==2 and len({c for r,c in comp})==1:
            for r,c in comp: out[r][c]=2
    return out
